use strict;
use warnings;

# Small nonnegative big integers, little-endian base 1e9.
my $BASE = 1000000000;
sub bn { return [0 + $_[0]]; }
sub cp { return [@{$_[0]}]; }
sub norm {
    my ($a) = @_;
    pop @$a while @$a > 1 && $a->[-1] == 0;
    return $a;
}
sub cmpbn {
    my ($a, $b) = @_;
    return @$a <=> @$b if @$a != @$b;
    for (my $i = $#$a; $i >= 0; --$i) {
        return $a->[$i] <=> $b->[$i] if $a->[$i] != $b->[$i];
    }
    return 0;
}
sub adds {
    my ($a, $v) = @_;
    my $i = 0;
    while ($v || $i < @$a) {
        $a->[$i] //= 0;
        my $x = $a->[$i] + ($v % $BASE);
        $v = int($v / $BASE);
        if ($x >= $BASE) { $x -= $BASE; $v++; }
        $a->[$i] = $x;
        $i++;
    }
    return $a;
}
sub subs {
    my ($a, $v) = @_;
    my $i = 0;
    my $borrow = $v;
    while ($borrow) {
        my $x = $a->[$i] - ($borrow % $BASE);
        $borrow = int($borrow / $BASE);
        if ($x < 0) { $x += $BASE; $borrow++; }
        $a->[$i] = $x;
        $i++;
    }
    return norm($a);
}
sub subbn {
    my ($a, $b) = @_;
    die 'negative big integer' if cmpbn($a, $b) < 0;
    my @r;
    my $borrow = 0;
    for (my $i = 0; $i < @$a; ++$i) {
        my $x = $a->[$i] - ($b->[$i] // 0) - $borrow;
        if ($x < 0) { $x += $BASE; $borrow = 1; } else { $borrow = 0; }
        push @r, $x;
    }
    return norm(\@r);
}
sub muls {
    my ($a, $m) = @_;
    my $carry = 0;
    for my $i (0 .. $#$a) {
        my $x = $a->[$i] * $m + $carry;
        $a->[$i] = $x % $BASE;
        $carry = int($x / $BASE);
    }
    push @$a, $carry while $carry;
    return $a;
}
sub divs {
    my ($a, $d) = @_;
    my @q;
    my $rem = 0;
    for (my $i = $#$a; $i >= 0; --$i) {
        my $cur = $rem * $BASE + $a->[$i];
        my $digit = int($cur / $d);
        $rem = $cur % $d;
        unshift @q, $digit;
    }
    return norm(\@q);
}
sub small {
    my ($a) = @_;
    die 'expected small integer' if @$a > 1;
    return $a->[0];
}

